import { beforeAll, describe, expect, it } from "vitest";
import { createRequire } from "module";
import fs from "node:fs";

const require = createRequire(import.meta.url);
const LL = require("../../level-logic");
const Cal = require("../../calibration-manager");
const { createSessionTracker } = require("../../session-tracker");
const h = require("./helpers/worklet-harness");

// Synthetic speech generated by macOS say for the 2026-11-20 research replay;
// resampled to mono 16 kHz PCM16. Production worklet, no injected gate decisions.
const wav = fs.readFileSync(new URL("../fixtures/speech-tts.wav", import.meta.url));
let sampleRate, raw;
for (let p = 12; p + 8 <= wav.length;) {
  const tag = wav.toString("ascii", p, p + 4);
  const bytes = wav.readUInt32LE(p + 4);
  if (tag === "fmt ") {
    if (wav.readUInt16LE(p + 8) !== 1 || wav.readUInt16LE(p + 10) !== 1 || wav.readUInt16LE(p + 22) !== 16)
      throw new Error("Expected mono PCM16 fixture");
    sampleRate = wav.readUInt32LE(p + 12);
  }
  if (tag === "data") {
    raw = Float32Array.from({ length: bytes / 2 }, (_, i) => wav.readInt16LE(p + 8 + i * 2) / 32768);
  }
  p += 8 + bytes + (bytes % 2);
}
const rms = Math.sqrt(raw.reduce((s, v) => s + v * v, 0) / raw.length);
const gain = Math.pow(10, -32 / 20) / rms;

function replay(segments) {
  const w = h.createWorklet(sampleRate);
  w.feed(h.noise(3000, -62, sampleRate, 99)); // settle the gate, outside measured clocks
  let cursor = 0;
  return segments.flatMap(({ ms, offset, pauses = false }) => {
    const samples = h.noise(ms, -62, sampleRate, 5);
    const g = gain * Math.pow(10, offset / 20);
    for (let i = 0; i < samples.length; i++, cursor++) {
      // Insert 1.2 s of room tone after every 4 s of source speech.
      const paused = pauses && (i / sampleRate * 1000) % 5200 >= 4000;
      if (!paused) samples[i] += raw[cursor % raw.length] * g;
      else cursor--; // resume the same source sample after the pause
    }
    return w.feed(samples);
  });
}

let baselineDb, calibration, calibrationFrames;
const offsetRuns = new Map();
beforeAll(() => {
  calibrationFrames = replay([{ ms: 60000, offset: 0 }]);
  const cal = Cal.createCalibrationManager();
  cal.start();
  for (const f of calibrationFrames) {
    calibration = cal.addFrame(f);
    if (calibration) break;
  }
  expect(calibration?.status).toBe("ok");
  baselineDb = calibration.baselineDb;
  for (const offset of [0, 3, 6, 8, 10, 12, 15])
    offsetRuns.set(offset, track(replay([{ ms: 60000, offset }])));
}, 30000);

function track(frames) {
  const t = LL.createDecisionTracker({ baselineDb });
  let audioMs = 0, voicedMs = 0;
  const rows = frames.map(f => {
    const d = t.update(f);
    audioMs += f.frameMs;
    if (d.speaking) voicedMs += f.frameMs;
    return { f, d, audioMs, voicedMs, snapshot: t.snapshot() };
  });
  return { rows, t, audioMs, voicedMs };
}

// AC-12: compare the held zone with unrounded thresholds (output tolerance
// 0.1 dB), and independently check delayed latch/recovery semantics.
function assertDecisions(rows) {
  let recoveryMs = 0;
  for (const { f, d } of rows) {
    expect(d.level).toBe(d.relDb === null ? 0 : LL.relativeLevel(d.relDb));
    expect(d.visual).toBe(LL.zoneToVisual(d.zone));
    if (d.relDb === null) {
      expect(d.heldZone).toBeNull();
      expect(d.zone).toBe("silent");
      continue;
    }
    if (d.heldZone === "normal") expect(d.relDb).toBeLessThan(6.1);
    else if (d.heldZone === "warning") {
      expect(d.relDb).toBeGreaterThanOrEqual(3.9);
      expect(d.relDb).toBeLessThan(10.1);
    } else {
      expect(d.heldZone).toBe("danger");
      expect(d.relDb).toBeGreaterThanOrEqual(7.9);
    }
    if (d.speaking) {
      recoveryMs = d.heldZone === "danger" ? 0 : recoveryMs + f.frameMs;
      if (recoveryMs >= 1000) expect(d.zone).not.toBe("danger");
    }
    if (d.zone !== "danger") expect(d.zone).toBe(d.heldZone === "danger" ? "warning" : d.heldZone);
  }
}

function metrics(run) {
  const shares = { silent: 0, normal: 0, warning: 0, danger: 0 };
  let prev = null, changes = 0;
  for (const { f, d } of run.rows) {
    shares[d.zone] += f.frameMs;
    if (d.zone !== "silent") {
      if (prev !== null && prev !== d.zone) changes++;
      prev = d.zone;
    }
  }
  return {
    audioMs: run.audioMs, voicedMs: run.voicedMs,
    stateShare: Object.fromEntries(Object.entries(shares).map(([k,v]) => [k, +(v / run.audioMs * 100).toFixed(1)])),
    changesPerMinute: changes * 60000 / run.audioMs,
    alertMs: run.rows.find(r => r.d.zone === "danger")?.audioMs ?? null,
  };
}

describe("recorded PCM → real worklet → calibration → decision replay", () => {
  it("AC-15: calibration uses at least 10 s voiced and its mean power", () => {
    expect(sampleRate).toBe(16000);
    expect(wav.length).toBeLessThan(2000000);
    expect(Cal.CALIBRATION_VERSION).toBe(3);
    expect(calibration.speechMs).toBeGreaterThanOrEqual(10000);
    let voicedMs = 0, energy = 0;
    const cal = Cal.createCalibrationManager();
    cal.start();
    for (const f of calibrationFrames) {
      if (f.voiced) { voicedMs += f.frameMs; energy += Math.pow(10, f.dbfs / 10) * f.frameMs; }
      const result = cal.addFrame(f);
      if (voicedMs < 10000) expect(result).toBeNull();
      if (result) break;
      expect(cal.getProgress()).toBeCloseTo(voicedMs / 10000, 8);
    }
    expect(baselineDb).toBeCloseTo(10 * Math.log10(energy / voicedMs), 1);
    const all = calibrationFrames.filter(f => f.voiced);
    const active = 10 * Math.log10(all.reduce((s,f) => s + Math.pow(10, f.dbfs / 10) * f.frameMs, 0) /
      all.reduce((s,f) => s + f.frameMs, 0));
    expect(Math.abs(baselineDb - active)).toBeLessThanOrEqual(1);
  });

  it("AC-1…4, AC-12: steady offsets, no false cue, prompt alert", () => {
    const table = Array.from(offsetRuns, ([offset, run]) => ({ offset, ...metrics(run) }));
    console.log("REPLAY OFFSETS", JSON.stringify(table));
    for (const [offset, run] of offsetRuns) {
      const m = metrics(run);
      assertDecisions(run.rows);
      expect(m.audioMs).toBeGreaterThanOrEqual(60000);
      expect(m.changesPerMinute, `offset ${offset}`).toBeLessThanOrEqual(4);
      if (offset <= 3) expect(run.rows.every(r => ["normal", "silent"].includes(r.d.zone))).toBe(true);
      if (offset === 8) expect(m.alertMs).toBeNull();
      if (offset === 10 || offset === 12) {
        expect(m.alertMs).not.toBeNull();
        expect(m.alertMs).toBeLessThanOrEqual(7000);
      }
    }
  });

  it("AC-5: 1.2 s pauses every 4 s do not reset loud-speech accumulation", () => {
    const run = track(replay([{ ms: 60000, offset: 12, pauses: true }]));
    const m = metrics(run);
    console.log("REPLAY PAUSES", JSON.stringify(m));
    expect(m.alertMs).not.toBeNull();
    expect(m.alertMs).toBeLessThanOrEqual(9000);
  });

  it.each([10, 12, 15])("AC-7, AC-12: +%s dB recovers within 4000 accepted ms, no re-latch", offset => {
    const run = track(replay([{ ms: 20000, offset }, { ms: 40000, offset: 0 }]));
    assertDecisions(run.rows);
    expect(run.rows.some(r => r.audioMs <= 20000 && r.d.zone === "danger")).toBe(true);
    const switched = run.rows.find(r => r.audioMs === 20000);
    const clear = run.rows.find(r => r.audioMs > 20000 && r.d.zone !== "danger");
    const acceptedRecoveryMs = clear.voicedMs - switched.voicedMs;
    console.log("REPLAY RECOVERY", JSON.stringify({ offset, audioMs: clear.audioMs - 20000, acceptedRecoveryMs }));
    expect(clear.d.speaking).toBe(true); // speech recovery, not Listening/silence reset
    expect(acceptedRecoveryMs).toBeLessThanOrEqual(4000);
    expect(run.rows.filter(r => r.audioMs >= clear.audioMs).every(r => r.d.zone !== "danger")).toBe(true);
    expect(run.audioMs - clear.audioMs).toBeGreaterThanOrEqual(20000);
  });

  it("AC-8: real hangover and far talkers cannot extend a silent episode", () => {
    const frames = replay([{ ms: 20000, offset: 12 }, { ms: 6000, offset: -Infinity }, { ms: 34000, offset: -20 }]);
    const run = track(frames);
    expect(run.rows.some(r => r.d.zone === "danger")).toBe(true);
    const lastAccepted = run.rows.filter(r => r.d.speaking).at(-1);
    expect(lastAccepted.audioMs).toBeLessThan(21000); // RMS tail can precede gate hangover
    expect(frames.some(f => f.speech && !f.voiced)).toBe(true);
    const resetRows = run.rows.filter(r => r.audioMs >= lastAccepted.audioMs + 5000);
    expect(resetRows.length).toBeGreaterThan(0);
    expect(resetRows.every(r => r.d.zone === "silent" && r.d.relDb === null && r.d.heldZone === null)).toBe(true);
    // A fresh short voiced burst must refill the window, with no old latch.
    expect(run.t.update({ dbfs: baselineDb + 12, voiced: true, frameMs: 20 }).zone).toBe("silent");
  });

  it("AC-18, AC-12: one bounded re-anchor at 30000 accepted ms", () => {
    const reports = [];
    for (const offset of [-8, 0, 9, 10]) {
      const run = track(replay([{ ms: 90000, offset }, { ms: 10000, offset: offset === -8 ? -2 : offset }]));
      assertDecisions(run.rows);
      const first = run.rows.find(r => r.snapshot.reanchored);
      expect(first).toBeDefined();
      expect(first.voicedMs).toBe(30000);
      expect(run.rows.filter(r => r.voicedMs < 30000).every(r => !r.snapshot.reanchored && r.snapshot.reanchorDb === 0)).toBe(true);
      const adjustment = first.snapshot.reanchorDb;
      expect(first.snapshot.storedBaselineDb).toBe(baselineDb);
      expect(run.rows.filter(r => r.audioMs >= first.audioMs).every(r => r.snapshot.reanchorDb === adjustment)).toBe(true);
      if (offset === -8) {
        expect(adjustment).toBeCloseTo(-8, 0);
        expect(run.rows.at(-1).d.heldZone).toBe("warning");
      } else if (offset === 0) expect(adjustment).toBe(0);
      else {
        expect(adjustment).toBe(3);
        expect(first.d.heldZone).toBe("warning");
        if (offset === 10) {
          expect(first.d.zone).toBe("danger");
          const cleared = run.rows.find(r => r.audioMs >= first.audioMs && r.d.zone !== "danger");
          expect(cleared.voicedMs - first.voicedMs + first.f.frameMs).toBeLessThanOrEqual(1000);
          expect(cleared.d.relDb).toBeLessThan(8);
        }
      }
      reports.push({ offset, audioMs: first.audioMs, voicedMs: first.voicedMs, adjustment, heldZone: first.d.heldZone });
    }
    console.log("REPLAY REANCHOR", JSON.stringify(reports));
  }, 30000);

  it("AC-19: far talker stays Listening and contributes no speaking statistics", () => {
    const run = track(replay([{ ms: 60000, offset: -20 }]));
    expect(run.rows.some(r => r.f.voiced)).toBe(true); // gate alone would accept it
    expect(run.rows.every(r => r.d.zone === "silent" && !r.d.speaking)).toBe(true);
    const session = createSessionTracker({ baselineDb });
    for (const r of run.rows) session.recordFrame(r.d, r.f.frameMs);
    expect(session.finalize().speakingTime).toBe(0);
    expect(run.t.snapshot().reanchored).toBe(false);
  });
});
